import{_ as t,o as i,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2022-11-02","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2022-11-02","date":"2022-11-02T00:00:00.000Z","updated":"2022-11-02T00:00:00.000Z","tags":["Ceph","RGW","分布式存储","多对象删除","性能优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_RGW_Refactoring_Meeting_2022-11-02.md","filePath":"posts/2022/Ceph_RGW_Refactoring_Meeting_2022-11-02.md","lastUpdated":1780459816000}'),p={name:"posts/2022/Ceph_RGW_Refactoring_Meeting_2022-11-02.md"};function n(r,e,a,s,_,g){return i(),l("div",null,[...e[0]||(e[0]=[o("<p>本次会议讨论了Ceph RGW的多对象删除（multi-delete PR）实现细节和性能优化。主要内容包括：</p><ol><li><p><strong>多对象删除并发限制</strong>：Corey提出为每个对象启动新协程进行并发删除，但需要限制同时启动的协程数量。建议引入新的配置参数来控制并发协程数量，避免对集群造成过大的IOPS压力。</p></li><li><p><strong>性能问题与优化</strong>：Corey指出使用旋转磁盘和Erasure Coding的多对象删除操作会导致大量IOPS，影响集群性能。提出不存储数据在head对象中，仅存储元数据，以提高删除操作性能。</p></li><li><p><strong>存储类别的交互</strong>：讨论了通过配置不同的存储类别来影响head对象的数据存储，以及如何设置默认的存储类别。</p></li><li><p><strong>数据与元数据的存储策略</strong>：探讨了为什么数据需要与head对象一起存储，并提出在特定情况下可以考虑分离数据和元数据的存储。</p></li></ol><p>决定事项：</p><ul><li>Corey将开启一个新的PR，涉及上述讨论的配置变更，并在现有PR中添加QoS相关提交。</li><li>开发团队将在GitHub上进一步讨论和审查这些变更。</li></ul><p>后续行动计划：</p><ul><li>Corey将提交新的PR并添加相关提交。</li><li>开发团队将在GitHub上继续讨论和审查这些变更。</li></ul><p>会议还提醒开发者注意即将到来的开发者月度会议和虚拟Cephalicon会议。</p><p>在原始总结中，以下点是准确的：</p><ul><li>会议主题：讨论Ceph的多对象删除实现细节和性能优化。</li><li>参会人员：包括Jason、Corey、Casey、Rick等开发人员。</li><li>主要讨论内容：多对象删除并发限制、性能问题与优化、存储类别的交互、数据与元数据的存储策略。</li><li>决定事项：Corey将开启新的PR，并添加相关提交。</li><li>后续行动计划：继续在GitHub上讨论变更细节。</li></ul><p>可能的错误或遗漏：</p><ul><li>原始字幕内容中未提及的绩效计数器讨论。</li><li>原始字幕内容中提到的Anthony和Intel的讨论未在总结中体现。</li></ul><p>改进后的总结更详细地反映了会议内容，包括所有关键细节和后续行动计划。</p>",12)])])}const R=t(p,[["render",n]]);export{d as __pageData,R as default};
